mapper.select:
/* LeaveConversionPolicyMapper.selectConversionMinutes */
SELECT P.DAILY_CONV_MINUTES
  FROM TB_LEAVE_CONVERSION_POLICY P
 WHERE P.CMPNY_CD        = #{cmpnyCd}
   AND P.APPLY_FROM_DATE <= #{workYmd}
 ORDER BY P.APPLY_FROM_DATE DESC
 LIMIT 1

mapper.update:
/* LeaveConversionPolicyMapper.updateConversionPolicy */
UPDATE TB_LEAVE_CONVERSION_POLICY
   SET DAILY_CONV_MINUTES = #{dailyConvMinutes}
     , UPDATE_NO          = #{updateNo}
     , UPDATE_DATE        = NOW()
 WHERE CMPNY_CD        = #{cmpnyCd}
   AND APPLY_FROM_DATE = #{applyFromDate}

mapper.insert:
/* LeaveConversionPolicyMapper.insertConversionPolicy */
INSERT INTO TB_LEAVE_CONVERSION_POLICY (
      CMPNY_CD
    , APPLY_FROM_DATE
    , DAILY_CONV_MINUTES
    , INSERT_NO
    , INSERT_DATE
)
VALUES (
      #{cmpnyCd}
    , #{applyFromDate}
    , #{dailyConvMinutes}
    , #{insertNo}
    , NOW()
)
